/** Deterministic, bounded conversation digest built only from the stored
 *  record (FR-062). No model call, no timestamps beyond createdAt, no raw
 *  payloads, image bytes, permission messages, or credentials. Same record ->
 *  byte-identical digest. */
import type { ContentBlock } from "@agentclientprotocol/sdk";
import type { RecordEntry, SessionHeader, UpdateEntry } from "./record.ts";

export const DIGEST_FIRST_LINE =
  "[Conversation digest — generated by Obsidian Chat from the stored record; not written by the model]";
export const FULL_REPLAY_FIRST_LINE =
  "[Full transcript replay — generated by Obsidian Chat from the stored record; not written by the model]";

export const DIGEST_TURNS = 6;
export const USER_CHARS = 600;
export const ASSISTANT_CHARS = 900;
export const TOOL_LINES = 8;
export const FILE_LIMIT = 30;
export const ERROR_LIMIT = 5;
export const DIGEST_CHARS = 8_000;
export const FULL_REPLAY_CHARS = 100_000;

export interface DigestResult {
  text: string;
  turnsIncluded: number;
  turnsOmitted: number;
  chars: number;
  hash: string;
  truncated: boolean;
}

export interface DigestInput {
  header: SessionHeader;
  entries: RecordEntry[];
}

interface TurnDigest {
  turn: number;
  user: string;
  assistant: string;
  tools: string[];
}

/** Last N complete turns (turns with a recorded `turn` boundary). */
function completeTurns(entries: RecordEntry[]): TurnDigest[] {
  const turns = new Map<number, TurnDigest>();
  const complete = new Set<number>();
  for (const entry of entries) {
    if (entry.kind === "turn") {
      complete.add(entry.turn);
      continue;
    }
    if (entry.kind === "prompt") {
      const digest = turns.get(entry.turn) ?? { turn: entry.turn, user: "", assistant: "", tools: [] };
      digest.user = promptText(entry.blocks).text;
      turns.set(entry.turn, digest);
      continue;
    }
    if (entry.kind !== "update") continue;
    const digest = turns.get(entry.turn) ?? { turn: entry.turn, user: "", assistant: "", tools: [] };
    const message = messageText(entry);
    if (message) digest.assistant = message.text;
    const tool = toolLine(entry);
    if (tool) digest.tools.push(tool);
    turns.set(entry.turn, digest);
  }
  return [...turns.values()].filter((turn) => complete.has(turn.turn)).sort((a, b) => a.turn - b.turn);
}

function promptText(blocks: unknown): { text: string; truncated: boolean } {
  if (!Array.isArray(blocks)) return { text: "", truncated: false };
  const parts: string[] = [];
  for (const block of blocks) {
    const value = block as { type?: string; text?: string };
    if (value?.type === "text" && typeof value.text === "string") parts.push(value.text);
  }
  const full = redact(parts.join("\n"));
  return { text: full.slice(0, USER_CHARS), truncated: full.length > USER_CHARS };
}

function messageText(entry: UpdateEntry): { text: string; truncated: boolean } | null {
  const payload = entry.payload as Record<string, unknown> | undefined;
  if (!payload) return null;
  const kind = payload.sessionUpdate;
  if (kind === "agent_message_chunk" || kind === "agent_thought_chunk") {
    if (kind !== "agent_message_chunk") return null;
    const full = redact(contentText(payload.content));
    return { text: full.slice(0, ASSISTANT_CHARS), truncated: full.length > ASSISTANT_CHARS };
  }
  if (payload.type === "message" && payload.role === "agent") {
    const full = redact(String(payload.text ?? ""));
    return { text: full.slice(0, ASSISTANT_CHARS), truncated: full.length > ASSISTANT_CHARS };
  }
  return null;
}

function contentText(content: unknown): string {
  if (!content || typeof content !== "object") return "";
  const value = content as { type?: string; text?: string };
  return value.type === "text" ? String(value.text ?? "") : "";
}

function toolLine(entry: UpdateEntry): string | null {
  const payload = entry.payload as Record<string, unknown> | undefined;
  if (!payload) return null;
  let title: string | undefined;
  let kind: string | undefined;
  if (payload.sessionUpdate === "tool_call" || payload.sessionUpdate === "tool_call_update") {
    title = typeof payload.title === "string" ? payload.title : undefined;
    kind = typeof payload.kind === "string" ? payload.kind : undefined;
  } else if (payload.type === "tool_call") {
    const tool = (payload.toolCall ?? {}) as Record<string, unknown>;
    title = typeof tool.title === "string" ? tool.title : typeof tool.name === "string" ? tool.name : undefined;
    kind = typeof tool.kind === "string" ? tool.kind : undefined;
  } else {
    return null;
  }
  const label = [kind, title].filter(Boolean).join(" ");
  return label ? redact(label).slice(0, 160) : null;
}

/** Files touched, from tool-call locations and diff paths, de-duplicated. */
function filesTouched(entries: RecordEntry[], limit = FILE_LIMIT): { files: string[]; truncated: boolean } {
  const files = new Set<string>();
  let truncated = false;
  for (const entry of entries) {
    if (entry.kind !== "update") continue;
    const payload = entry.payload as Record<string, unknown> | undefined;
    if (!payload) continue;
    for (const location of locationsOf(payload)) {
      const path = String(location.path ?? "").replace(/^\/+/, "");
      if (path) files.add(path);
      if (files.size >= limit) return { files: [...files], truncated: true };
    }
    for (const content of contentOf(payload)) {
      if (content.type === "diff" && typeof content.path === "string") {
        files.add(content.path.replace(/^\/+/, ""));
        if (files.size >= limit) return { files: [...files], truncated: true };
      }
    }
  }
  return { files: [...files], truncated };
}

function locationsOf(payload: Record<string, unknown>): Array<{ path?: unknown }> {
  const locations = payload.locations;
  if (Array.isArray(locations)) return locations as Array<{ path?: unknown }>;
  const tool = payload.toolCall as Record<string, unknown> | undefined;
  if (tool && Array.isArray(tool.locations)) return tool.locations as Array<{ path?: unknown }>;
  return [];
}

function contentOf(payload: Record<string, unknown>): Array<{ type?: string; path?: string }> {
  if (Array.isArray(payload.content)) return payload.content as Array<{ type?: string; path?: string }>;
  const tool = payload.toolCall as Record<string, unknown> | undefined;
  if (tool && Array.isArray(tool.content)) return tool.content as Array<{ type?: string; path?: string }>;
  return [];
}

/** Errors, safe messages only, bounded. */
function errorsOf(entries: RecordEntry[], limit = ERROR_LIMIT): { errors: string[]; truncated: boolean } {
  const errors: string[] = [];
  let seen = 0;
  for (const entry of entries) {
    if (entry.kind !== "error") continue;
    seen += 1;
    if (errors.length < limit) errors.push(redact(entry.message).slice(0, 240));
  }
  return { errors, truncated: seen > limit };
}

/** Credential-looking strings never enter a digest. */
export function redact(text: string): string {
  return text
    .replace(/\b(?:sk|pk|ghp|github_pat|xox[baprs])[-_][A-Za-z0-9_-]{8,}\b/gi, "***")
    .replace(/((?:token|api[_-]?key|secret|password|authorization)\s*[=:]\s*)\S+/gi, "$1***")
    .replace(/Bearer\s+[A-Za-z0-9._-]+/gi, "Bearer ***");
}

export function buildDigest(input: DigestInput): DigestResult {
  const allTurns = completeTurns(input.entries);
  const included = allTurns.slice(-DIGEST_TURNS);
  const omitted = allTurns.length - included.length;
  let truncated = omitted > 0;
  const lines: string[] = [DIGEST_FIRST_LINE];
  lines.push(`Title: ${input.header.title ?? "(untitled)"}`);
  lines.push(`Created: ${new Date(input.header.createdAt).toISOString()}`);
  lines.push(`Turns: ${included.length} included${omitted > 0 ? ` (${omitted} earlier omitted)` : ""}`);
  let toolCount = 0;
  let fieldTruncated = false;
  for (const turn of included) {
    lines.push(`Turn ${turn.turn}:`);
    lines.push(`User: ${turn.user}`);
    if (turn.assistant) lines.push(`Assistant: ${turn.assistant.slice(0, ASSISTANT_CHARS)}`);
    for (const tool of turn.tools) {
      if (toolCount >= TOOL_LINES) {
        truncated = true;
        break;
      }
      lines.push(`Tool: ${tool}`);
      toolCount += 1;
    }
  }
  // Field-level truncation also counts as a bound hit.
  for (const turn of included) {
    const source = input.entries.find(
      (entry) => entry.kind === "prompt" && (entry as { turn?: number }).turn === turn.turn,
    );
    if (source && (source as { blocks?: unknown }).blocks) {
      if (promptText((source as { blocks?: unknown }).blocks).truncated) fieldTruncated = true;
    }
  }
  const filesResult = filesTouched(input.entries);
  const files = filesResult.files;
  truncated = truncated || filesResult.truncated || fieldTruncated;
  if (files.length) lines.push(`Files touched: ${files.join(", ")}`);
  const errorsResult = errorsOf(input.entries);
  const errors = errorsResult.errors;
  truncated = truncated || errorsResult.truncated;
  if (errors.length) lines.push(`Errors: ${errors.join(" | ")}`);
  lines.push("[end digest]");
  let text = lines.join("\n");
  if (text.length > DIGEST_CHARS) {
    truncated = true;
    const marker = "\n[end digest; truncated]";
    text = `${text.slice(0, DIGEST_CHARS - marker.length)}${marker}`;
  } else if (truncated) {
    text = `${text.slice(0, -"[end digest]".length)}[end digest; truncated]`;
  }
  return {
    text,
    turnsIncluded: included.length,
    turnsOmitted: omitted,
    chars: text.length,
    hash: fnv(text),
    truncated,
  };
}

/** Bounded full-transcript projection for the advanced replay choice (FR-062). */
export function buildFullReplay(input: DigestInput): DigestResult {
  const lines: string[] = [FULL_REPLAY_FIRST_LINE];
  lines.push(`Title: ${input.header.title ?? "(untitled)"}`);
  lines.push(`Created: ${new Date(input.header.createdAt).toISOString()}`);
  for (const entry of input.entries) {
    if (entry.kind === "prompt") {
      const text = promptText(entry.blocks).text;
      if (text) lines.push(`User: ${text}`);
    } else if (entry.kind === "update") {
      const message = messageText(entry);
      if (message) lines.push(`Assistant: ${message.text}`);
      const tool = toolLine(entry);
      if (tool) lines.push(`Tool: ${tool}`);
    } else if (entry.kind === "turn") {
      lines.push(`--- turn ${entry.turn} ${entry.interrupted ? "interrupted" : entry.stopReason ?? "ended"} ---`);
    } else if (entry.kind === "error") {
      lines.push(`Error: ${redact(entry.message)}`);
    }
  }
  lines.push("[end replay]");
  let text = lines.join("\n");
  let truncated = false;
  if (text.length > FULL_REPLAY_CHARS) {
    truncated = true;
    const marker = "\n[end replay; truncated]";
    text = `${text.slice(0, FULL_REPLAY_CHARS - marker.length)}${marker}`;
  }
  return { text, turnsIncluded: completeTurns(input.entries).length, turnsOmitted: 0, chars: text.length, hash: fnv(text), truncated };
}

/** One labelled ContentBlock prepended to the first prompt (never a visible
 *  separate user turn). */
export function digestBlock(text: string): ContentBlock {
  return { type: "text", text } as ContentBlock;
}

function fnv(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}
